"""Génère le cours à partir de slides.json ; conserve les 77 originaux."""
from pathlib import Path
import html,json,re
from course_visuals import render_diagram
ROOT=Path(__file__).resolve().parents[1]
DIR=ROOT/'cours/conception-audio-video'
data=json.loads((DIR/'slides.json').read_text())
originals=json.loads((DIR/'contenu-source.json').read_text())
old=(DIR/'index.html').read_text()
labels={html.unescape(url):html.unescape(re.sub('<.*?>','',label)).replace(' ↗','') for url,label in re.findall(r'<a href="(https?://[^"]+)"[^>]*>(.*?)</a>',old)}
def e(x):return html.escape(re.sub(r" (?=[?!:;])", "\u202f", str(x)),quote=True)
nav='';parts=[];i=0;total=sum(len(c['slides']) for c in data['chapters'])
for ci,c in enumerate(data['chapters'],1):
 nav+=f'<a href="#chapitre-{e(c["id"])}"><span>{ci:02}</span>{e(c["title"])}</a>'
 cards=[]
 for s in c['slides']:
  i+=1;kind=s['kind'];tags={'atelier':'ATELIER','cours':'COURS','ouverture':'LE CAP'}
  new='<span class="added">COMPLÉMENT</span>' if s['added'] else ''
  blocks=''.join(f'<div class="idea"><span class="idea-no">{j:02}</span><h4>{e(b["title"])}</h4><p>{e(b["text"])}</p></div>' for j,b in enumerate(s['items'],1))
  table=''
  if s.get('table'):
   t=s['table'];table='<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in t['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+e(v)+'</th>') if k==0 else '<td>'+e(v)+'</td>' for k,v in enumerate(row))+'</tr>' for row in t['rows'])+'</tbody></table></div>'
  resources=[]
  for n in s['source_pages']:
   for u in originals[n-1]['links']:
    if u not in resources:resources.append(u)
  rlinks=''
  if resources:rlinks='<details class="links"><summary>Exemples et ressources du support ('+str(len(resources))+')</summary><ul>'+''.join(f'<li><a href="{e(u)}" target="_blank" rel="noopener noreferrer">{e(labels.get(u,u.split("/")[2]))} ↗</a></li>' for u in resources)+'</ul></details>'
  key=f'<aside class="takeaway"><span>À RETENIR</span><p>{e(s["takeaway"])}</p></aside>' if s['takeaway'] else ''
  count=len(s['items']);work=''
  if kind=='atelier':
   duration=re.search(r'\b(?:5|45|60) minutes|une heure',s['lead'])
   work=f'<aside class="workshop-meta"><span class="squiggle" aria-hidden="true">〰</span><small>ATELIER</small><strong>À VOUS<br>DE JOUER !</strong><div>{e(duration[0]) if duration else "Jalon de projet"}</div><p>{"En individuel" if "individuel" in s["title"].lower() else "En groupe"}</p><span class="meta-bottom">TESTER · CRÉER · PARTAGER</span></aside>'
  diagram=render_diagram(s.get('diagram'))
  portrait='<figure class="trainer-portrait" role="img" aria-label="Portrait de Nicolas Genaudet"><img src="assets/diapo-02.jpg" alt="" aria-hidden="true" width="1400" height="788"></figure>' if s.get('portrait') else ''
  body=f'<div class="slide-body"><header><div class="slide-eyebrow">{tags[kind]} {new}</div><h3>{e(s["title"])}</h3><p class="slide-lead">{e(s["lead"])}</p></header><div class="ideas cols-{count}">{blocks}</div>{portrait}{table}{diagram}{key}{rlinks}</div>'
  sources=', '.join(str(n) for n in s['source_pages']) or 'Complément pédagogique'
  cards.append(f'<article class="lesson slide {kind} diagram-{s.get("diagram", "none")} {"trainer" if s.get("portrait") else ""} {"records" if s.get("records") else ""}" id="slide-{i}" data-index="{i-1}" aria-labelledby="slide-title-{i}"><div class="slide-brand"><span class="pilot">INSEEC</span><span>INSEEC · CONCEPTION AUDIO & VIDÉO</span></div><div class="slide-layout">{work}{body}</div><footer class="slide-footer"><span>Nicolas Genaudet · MSc2 MCSC</span><span>SLIDE {i:02} / {total:02}</span></footer><span class="sr-only">Référence au support : {e(sources)}</span></article>'.replace('<h3>','<h3 id="slide-title-'+str(i)+'">',1))
 parts.append(f'<section class="chapter" id="chapitre-{e(c["id"])}"><header class="chapter-head"><span class="chapter-index">{ci:02}</span><div><span class="eyebrow">CAP SUR LA SUITE</span><h2>{e(c["title"])}</h2><p>{e(c["description"])}</p></div></header>'+''.join(cards)+'</section>')
gallery=''.join(f'<details class="source"><summary><span>{p["page"]:02}</span> {e((p["text"].splitlines() or ["Visuel"])[0][:100])}</summary><img src="assets/diapo-{p["page"]:02}.jpg" alt="Diapositive originale {p["page"]}" loading="lazy" width="1400" height="788"></details>' for p in originals)
refs=''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])} ↗</a></li>' for s in data['sources'])
page='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Cours INSEEC de conception audio et vidéo : stratégie, script, tournage, audio, montage et diffusion en 18 heures."><title>Conception audio & vidéo · INSEEC</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#cours">Aller au cours</a><aside class="sidebar"><a class="brand" href="#accueil"><span class="pilot">INSEEC</span><small>LES SUPPORTS DE NICOLAS GENAUDET</small></a><div class="nav-label">LE PARCOURS · 18 HEURES</div><nav aria-label="Chapitres">__NAV__</nav><div class="sidebar-bottom"><a href="#references">Sources et ressources ↗</a><a href="#originaux">Les 77 slides originales ↗</a><small>INSEEC · MSc2 MCSC<br>Support d’origine 2025–2026<br>Version enrichie · octobre 2026</small></div></aside><div class="page"><header class="topbar"><span>ESPACE ÉTUDIANTS <b>/</b> CONCEPTION AUDIO & VIDÉO</span><div><button id="present" type="button">Lire en diaporama <span aria-hidden="true">▶</span></button><button id="print" type="button">Imprimer</button></div></header><main id="cours"><section class="hero" id="accueil"><div class="hero-inner"><span class="eyebrow">FORMATION INSEEC</span><h1>Conception<br>audio <span>& vidéo.</span></h1><p>De la première idée aux dernières secondes.<br>Apprenez à raconter, produire et convaincre.</p><div class="pills"><span>18 HEURES</span><span>MSc2 MCSC</span><span>3 VIDÉOS À CRÉER</span></div><a class="primary" href="#chapitre-cap">À l’abordage ! <span>↘</span></a></div><div class="hero-visual" aria-hidden="true"><span class="visual-note">L’IDÉE PREND LE LARGE.</span><div class="boat"><div class="mast"></div><div class="sail sail-one"></div><div class="sail sail-two"></div><div class="hull"></div></div><div class="sun"></div><div class="ocean ocean-one"></div><div class="ocean ocean-two"></div><span class="visual-caption">STRATÉGIE → CRÉATION → DIFFUSION</span></div><span class="hero-wave" aria-hidden="true">∿ ∿ ∿ ∿ ∿ ∿ ∿ ∿ ∿ ∿ ∿ ∿</span></section><section class="mission-banner"><div><span class="eyebrow">LE FIL ROUGE</span><h2>Un produit. Une équipe.<br><em>Trois vidéos.</em></h2></div><div class="mission-facts"><div><strong>1 min 30</strong><span>La présentation produit</span></div><div><strong>2 × 30–45 s</strong><span>Les vidéos complémentaires</span></div><div><strong>50 % / 50 %</strong><span>Suivi / présentation finale</span></div></div></section><div class="course-tools"><div><span class="eyebrow">LE COURS EN SLIDES</span><p>__TOTAL__ slides · 10 chapitres · 17 compléments pédagogiques</p></div><label class="search-label" for="search"><span class="sr-only">Rechercher dans le cours</span><input id="search" type="search" placeholder="Chercher : script, son, atelier…" autocomplete="off"></label><span id="results" role="status" aria-live="polite"></span></div><p id="empty" hidden>Aucune slide trouvée. Essayez un autre mot.</p>__PARTS__<section class="reference-section" id="references"><span class="eyebrow">POUR ALLER PLUS LOIN</span><h2>Sources des compléments</h2><p>Références consultées le 27 octobre 2026. Les écrans et menus peuvent évoluer avec les versions.</p><ul>__REFS__</ul></section><section class="chapter originals" id="originaux"><header class="chapter-head"><span class="chapter-index">↺</span><div><span class="eyebrow">ARCHIVES DU SUPPORT</span><h2>Les 77 diapositives originales</h2><p>Le PDF d’origine est conservé visuellement. Certains éléments ont été corrigés ou précisés dans le cours révisé : utilisez les slides ci-dessus pour les consignes actuelles.</p></div></header>__GALLERY__</section><footer class="page-footer">Conception audio & vidéo · Nicolas Genaudet · INSEEC · Support d’origine Pilot’in 2025–2026.<br>Version web enrichie · 27 octobre 2026.</footer></main></div><div class="presentation-toolbar" hidden aria-label="Commandes du diaporama"><button id="previous-slide" type="button" aria-label="Slide précédente">←</button><span id="slide-status" role="status" aria-live="polite"></span><button id="next-slide" type="button" aria-label="Slide suivante">→</button><button id="exit-presentation" type="button">Quitter <kbd>Échap</kbd></button></div><a class="back-top" href="#accueil" aria-label="Retour en haut">↑</a><script src="app.js"></script></body></html>'''
page=page.replace('__NAV__',nav).replace('__PARTS__',''.join(parts)).replace('__TOTAL__',str(total)).replace('__REFS__',refs).replace('__GALLERY__',gallery)
(DIR/'index.html').write_text(page)
print(f'{total} slides générées ; {len(originals)} originaux conservés.')
